fn handle_visual_key(&mut self, key: UiKey) -> Vec<UiAction> {
    match key {
        UiKey::Esc => {
            self.cancel_visual_selection();
            self.mode = UiMode::Command;
        }
        UiKey::Char('y') => {
            self.queue_visual_yank(None);
        }
        UiKey::Char('Y') => {
            self.queue_visual_yank(Some(VisualMode::Line));
        }
        UiKey::Char('h') | UiKey::Left => {
            self.move_visual_cursor(0, -1);
        }
        UiKey::Char('j') | UiKey::Down => {
            self.move_visual_cursor(1, 0);
        }
        UiKey::Char('k') | UiKey::Up => {
            self.move_visual_cursor(-1, 0);
        }
        UiKey::Char('l') | UiKey::Right => {
            self.move_visual_cursor(0, 1);
        }
        _ => {}
    }
    Vec::new()
}

fn start_visual_selection(&mut self, mode: VisualMode) {
    self.pending = None;
    let position = self.visual_start_position();
    self.visual_selection = Some(VisualSelection {
        focus: self.focus,
        mode,
        anchor: position,
        cursor: position,
    });
}

fn cancel_visual_selection(&mut self) {
    self.visual_selection = None;
}

fn visual_start_position(&self) -> VisualPosition {
    match self.focus {
        PaneFocus::Left => VisualPosition {
            row: self.control_selected,
            column: 0,
        },
        PaneFocus::Right => VisualPosition { row: 0, column: 0 },
    }
}

fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
    let Some(selection) = self.visual_selection.as_mut() else {
        return;
    };

    selection.cursor.row = if row_delta.is_negative() {
        selection.cursor.row.saturating_sub(row_delta.unsigned_abs())
    } else {
        selection.cursor.row.saturating_add(row_delta as usize)
    };
    selection.cursor.column = if column_delta.is_negative() {
        selection
            .cursor
            .column
            .saturating_sub(column_delta.unsigned_abs())
    } else {
        selection.cursor.column.saturating_add(column_delta as usize)
    };
}

fn queue_visual_yank(&mut self, forced_mode: Option<VisualMode>) {
    let Some(selection) = self.visual_selection.take() else {
        return;
    };
    self.pending_yank.set(Some(YankRequest {
        focus: selection.focus,
        mode: forced_mode.unwrap_or(selection.mode),
        anchor: selection.anchor,
        cursor: selection.cursor,
    }));
    self.mode = UiMode::Command;
}

fn clipboard_prefix(&self, right_content: &str) -> String {
    let Some(request) = self.pending_yank.take() else {
        return String::new();
    };
    let lines = match request.focus {
        PaneFocus::Left => self.left_pane_display_lines(self.layout().left_width),
        PaneFocus::Right => self.right_pane_display_lines(right_content),
    };
    let Some(text) = selected_text(&lines, request) else {
        return String::new();
    };
    if text.is_empty() {
        String::new()
    } else {
        osc52_clipboard_sequence(&text)
    }
}

